layer.css:
[data-ryt="pitch"] { color: var(--ryt-text); background-color: rgb(249, 249, 249); border-left: 4px solid rgb(67, 159, 85); border-radius: 0px; font-family: var(--ryt-font-body); font-size: 14px; font-weight: 400; font-style: italic; line-height: 1.714; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 20px; padding-right: 20px; padding-bottom: 20px; padding-left: 20px; transition: all; border-top: none; border-right: none; border-bottom: none }
[data-ryt="footer"] { color: var(--ryt-text); font-style: normal; letter-spacing: normal; text-transform: none }
article[data-ryt="rec-card"] { border-top: 2px dashed var(--ryt-border); border-radius: 0px; transition: all; border-right: none; border-bottom: none; border-left: none }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: #519f61; border-radius: 0px; font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-line: underline; text-decoration-style: solid; text-decoration-color: rgb(87, 173, 104); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="section"] > h2 { color: rgb(85, 85, 85); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 400; font-style: normal; line-height: 1.25; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(85, 85, 85); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="brand"] { color: rgb(67, 159, 85); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 36px; font-weight: 400; font-style: normal; line-height: 1.167; letter-spacing: -2px; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(67, 159, 85); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="nav"] a { color: #8e8e8e; border-radius: 0px; font-family: var(--ryt-font-body); font-size: 14px; font-weight: 400; font-style: normal; line-height: 1.714; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-bg); text-decoration-thickness: auto; text-underline-offset: auto; text-shadow: rgba(0, 0, 0, 0.4) 0px 1px 1px; padding-top: 8px; padding-right: 12px; padding-bottom: 0px; padding-left: 10px; transition: all }
[data-ryt="review"] { color: var(--ryt-text); font-family: var(--ryt-font-body); font-size: 14px; font-weight: 400; font-style: normal; line-height: 1.714; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="credit"], [data-ryt="eyebrow"] { color: var(--ryt-text); font-family: var(--ryt-font-body); font-size: 12px; font-weight: 400; font-style: normal; line-height: 2; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] a { color: #519f61; border-radius: 0px; font-family: var(--ryt-font-body); font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(87, 173, 104); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
body { background-image: url("{{assets}}/hugo-travelify-theme_8e0f9a5fa1b3/background.png"); background-size: auto; background-position: 0% 0%; background-repeat: repeat }
[data-ryt="rec-card"] [data-ryt="title"] { color: rgb(27, 30, 31); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 32px; font-weight: 400; font-style: normal; line-height: 1.4; letter-spacing: -1px; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(27, 30, 31); text-decoration-thickness: auto; text-underline-offset: auto; text-shadow: var(--ryt-bg) 0px 1px 0px; transition: 0.3s ease-out }
[data-ryt="rec-card"] [data-ryt="title"] a:hover { color: rgb(67, 159, 85); text-decoration-line: none; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; color: rgb(67, 159, 85); text-decoration-line: none; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; color: rgb(67, 159, 85) }
[data-ryt="nav"] a:hover { color: rgb(67, 159, 85); text-decoration-line: none; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; background-image: initial; background-color: rgb(67, 159, 85); box-shadow: rgba(0, 0, 0, 0.2) 0px 0px 4px inset; opacity: 1; color: rgb(67, 159, 85); color: rgb(67, 159, 85); text-decoration-line: none; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; background-image: initial; background-color: rgb(67, 159, 85); box-shadow: rgba(0, 0, 0, 0.2) 0px 0px 4px inset; opacity: 1; color: rgb(67, 159, 85); color: rgb(67, 159, 85); background-image: initial; background-color: rgb(67, 159, 85) }
[data-ryt="credit"] a:hover, [data-ryt="review"] a:hover, [data-ryt="bio"] a:hover { color: rgb(67, 159, 85); text-decoration-line: none; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; color: rgb(67, 159, 85); text-decoration-line: none; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; color: rgb(67, 159, 85) }
[data-ryt="footer"]::after { content: " "; display: block; width: 100%; color: var(--ryt-text); background-size: auto; background-position: 0% 0%; background-repeat: repeat; border-radius: 0px; font-family: var(--ryt-font-body); font-size: 0px; font-weight: 400; font-style: normal; line-height: 24px; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all; -webkit-text-fill-color: var(--ryt-text) }
[data-ryt="pitch"]::before { content: ""; display: inline; color: var(--ryt-text); background-size: auto; background-position: 0% 0%; background-repeat: repeat; border-radius: 0px; font-family: var(--ryt-font-body); font-size: 14px; font-weight: 400; font-style: italic; line-height: 1.714; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all; -webkit-text-fill-color: var(--ryt-text) }
[data-ryt="pitch"]::after { content: ""; display: inline; color: var(--ryt-text); background-size: auto; background-position: 0% 0%; background-repeat: repeat; border-radius: 0px; font-family: var(--ryt-font-body); font-size: 14px; font-weight: 400; font-style: italic; line-height: 1.714; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all; -webkit-text-fill-color: var(--ryt-text) }
